frappe.xcall("whatsapp_messaging.messaging.api.overview", {section: "messaging"}).then(data => {
 const root=root_element;
 root.querySelector(".wm-state").textContent=data.outbound_enabled ? "Outbound enabled" : "Outbound messaging is disabled";
 root.querySelector(".wm-help").textContent=data.accounts.length ? "Choose a card or shortcut to continue." : data.manager ? "Start by configuring a sender account in Administration. Outbound remains disabled until setup and validation are complete." : "No sender accounts are configured. Ask your System Manager to complete setup.";
 const cards=root.querySelector(".wm-cards");cards.replaceChildren();
 for (const card of data.cards) {
  const button=document.createElement("button");button.type="button";button.className="wm-card";
  const value=document.createElement("strong");value.textContent=card.value;
  const label=document.createElement("span");label.textContent=card.label;
  button.append(value,label);button.onclick=()=>{frappe.route_options=card.route_options;frappe.set_route(card.route);};cards.append(button);
 }
}).catch(()=>{root_element.querySelector(".wm-state").textContent="Unable to load this workspace. Refresh or check your access.";});

